// 2D procedural art for districts, shops, and dialog portraits: creatures, buildings, skies, ground, icons.
import { getSpecies } from '../data/species.js';
import { makeRng, hashStr, shade, mix, rgba, hsl, clamp, lerp } from '../util.js';

export function rr(ctx, x, y, w, h, r) { r = Math.min(r, w / 2, h / 2); ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }
export function label(ctx, text, x, y, size, color = '#fff', stroke = '#141a2e', align = 'center', font = '"Arial Rounded MT Bold", "Trebuchet MS", sans-serif') {
  ctx.font = `bold ${size}px ${font}`; ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, size * 0.16); ctx.strokeStyle = stroke; ctx.strokeText(text, x, y); ctx.fillStyle = color; ctx.fillText(text, x, y);
}
const circle = (ctx, x, y, r, fill, stroke, lw = 3) => { ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); } };
