    if (o.accessory === 'apron') { ctx.fillStyle = '#fff6e6'; rr(ctx, -bodyW / 2 + 8, -bodyH + 4, bodyW - 16, bodyH - 4, 10); ctx.fill(); ctx.stroke(); ctx.strokeStyle = '#d9534f'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(-14, -bodyH + 4); ctx.lineTo(-4, -bodyH - 6); ctx.moveTo(14, -bodyH + 4); ctx.lineTo(4, -bodyH - 6); ctx.stroke(); }
