    if (o.accessory === 'gear') { ctx.strokeStyle = '#ffd23f'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(-bodyW / 2 + 6, -bodyH + 10); ctx.lineTo(bodyW / 2 - 6, -bodyH + 40); ctx.stroke(); }
