  const headShape = () => { if (sp.head.shape === 'box') rr(ctx, hx - hw, hy - hh, hw * 2, hh * 2, 10); else if (sp.head.shape === 'gem') { ctx.beginPath(); for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2 - Math.PI / 2; ctx.lineTo(hx + Math.cos(a) * hw * 1.05, hy + Math.sin(a) * hh * 1.05); } ctx.closePath(); } else { ctx.beginPath(); ctx.ellipse(hx, hy, hw, hh, 0, 0, Math.PI * 2); } };
