  const ant = sp.features.find(f => f.startsWith('antenna:')); if (ant) { const n = +ant.split(':')[1]; for (let i = 0; i < n; i++) { const ax = n === 1 ? 0 : (i ? 18 : -18); ctx.strokeStyle = INK; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(hx + ax, hy - hh + 4); ctx.lineTo(hx + ax * 1.6, hy - hh - 34); ctx.stroke(); circle(ctx, hx + ax * 1.6, hy - hh - 38, 7, acc, INK); } }
