  if (sp.features.includes('flower')) { circle(ctx, hx, hy - hh - 10, 12, '#ffe66d', INK); for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2; circle(ctx, hx + Math.cos(a) * 18, hy - hh - 10 + Math.sin(a) * 18, 9, acc, INK, 2); } }
  if (sp.features.includes('leaves')) for (const sd of [-1, 1]) { ctx.fillStyle = '#3f9b3f'; ellipse(ctx, hx + sd * hw * 0.95, hy - hh * 0.2, 22, 10, '#3f9b3f', INK, 2.5, sd * 0.6); }
