  if (sp.features.includes('bubblehelm')) { ctx.strokeStyle = 'rgba(200,240,255,0.9)'; ctx.lineWidth = 4; ctx.beginPath(); ctx.ellipse(hx, hy, hw * 1.35, hh * 1.3, 0, 0, Math.PI * 2); ctx.stroke(); ctx.fillStyle = 'rgba(200,240,255,0.15)'; ctx.fill(); }
