  const eyePos = e.count === 1 ? [[0, 0]] : e.count === 3 ? [[-hw * 0.42, 0], [hw * 0.42, 0], [0, -hh * 0.45]] : e.count === 4 ? [[-hw * 0.35, 0], [hw * 0.35, 0], [-hw * 0.6, -hh * 0.35], [hw * 0.6, -hh * 0.35]] : e.count === 0 ? [] : [[-hw * 0.4, 0], [hw * 0.4, 0]];
  if (e.style === 'visor') { ctx.fillStyle = e.color || '#3ee8ff'; rr(ctx, hx - hw * 0.85, eyeY - 10, hw * 1.7, 20, 8); ctx.fill(); ctx.shadowColor = e.color || '#3ee8ff'; }
